// built-in and external agents. A built-in's UninstallHooks is in-process and
// idempotent, and its hook config can be partial or stale in a way
// AreHooksInstalled does not recognize as installed, so it is called regardless.
// Only external plugins — where the call is a mutating subprocess against a
// binary discovery found on $PATH — are skipped on a clean "no hooks".
func TestRunUninstall_BuiltinHooksRemovedWhenNotDetected(t *testing.T) {
	// Cannot use t.Parallel: mutates cwd and the agent registry.
	calls := registerFakeBuiltinHookAgent(t, "fake-builtin-undetected", nil)

	var stdout, stderr bytes.Buffer
	if err := runUninstall(context.Background(), &stdout, &stderr, true); err != nil {
		t.Fatalf("runUninstall() error = %v\\nstderr: %s", err, stderr.String())
	}

	if *calls == 0 {
		t.Errorf("a built-in agent absent from the installed set must still have UninstallHooks called, stdout:\\n%s", stdout.String())
	}
}

// TestRunUninstall_BuiltinHookFailureStillSucceeds pins that a built-in failure
// keeps the pre-existing contract: a warning and a zero exit. The non-zero exit
// is reserved for external plugins, which a re-run cannot reach once .entire/ —
// and with it the setting gating discovery — is gone. A built-in is always
// reachable: its leftover hooks keep the installed set non-empty.
func TestRunUninstall_BuiltinHookFailureStillSucceeds(t *testing.T) {
	// Cannot use t.Parallel: mutates cwd and the agent registry.
	registerFakeBuiltinHookAgent(t, "fake-builtin-failing", errors.New("mock builtin uninstall failure"))

	var stdout, stderr bytes.Buffer
	if err := runUninstall(context.Background(), &stdout, &stderr, true); err != nil {
		t.Fatalf("a built-in hook failure must not fail the uninstall, got error = %v\\nstderr: %s", err, stderr.String())
	}

	if !strings.Contains(stderr.String(), "Warning: failed to remove agent hooks") {
		t.Errorf("expected the failure to be warned about on stderr, got:\\n%s", stderr.String())
	}
	if !strings.Contains(stdout.String(), "uninstalled successfully") {
		t.Errorf("expected the uninstall to still report success, got:\\n%s", stdout.String())
	}
}

// TestRunUninstall_UncheckableExternalAgentStillUninstalled pins that a plugin
// that cannot say whether its hooks are installed is not treated as a clean
// "no hooks". Its hooks may well be installed, and .entire/ is about to be
// deleted, so this run is the user's last chance to remove them.
func TestRunUninstall_UncheckableExternalAgentStillUninstalled(t *testing.T) {
	// Cannot use t.Parallel: mutates $PATH, cwd, and the agent registry.
	const agentName = "ext-uninstall-uncheckable-test"
	installExternalAgentPluginForUninstall(t, agentName, true)
	t.Setenv("ENTIRE_TEST_FAIL_ARE_HOOKS_INSTALLED", "1")

	execLog := filepath.Join(t.TempDir(), "exec.log")
	t.Setenv("ENTIRE_TEST_EXEC_LOG", execLog)

	var stdout, stderr bytes.Buffer
	if err := runUninstall(context.Background(), &stdout, &stderr, true); err != nil {
		t.Fatalf("runUninstall() error = %v\\nstderr: %s", err, stderr.String())
	}

	data, err := os.ReadFile(execLog)
	if err != nil {
		t.Fatalf("reading exec log: %v (uninstall never executed the plugin)", err)
	}
	if !strings.Contains(string(data), "uninstall-hooks") {
		t.Errorf("a plugin that could not be probed must still be asked to uninstall, exec log:\\n%s", data)
	}
}

// TestRunUninstall_SummaryNamesUncheckableExternalAgent pins the other half: the
// user approving the uninstall is told the plugin's state is unknown, rather
// than it being silently absent from the summary as having nothing to remove.
func TestRunUninstall_SummaryNamesUncheckableExternalAgent(t *testing.T) {
	// Cannot use t.Parallel: mutates $PATH, cwd, and the agent registry.
	const agentName = "ext-uninstall-uncheckable-summary-test"
	installExternalAgentPluginForUninstall(t, agentName, true)
	t.Setenv("ENTIRE_TEST_FAIL_ARE_HOOKS_INSTALLED", "1")

	// force=false prints the summary, then stops at the no-terminal guard.
	var stdout, stderr bytes.Buffer
	if err := runUninstall(context.Background(), &stdout, &stderr, false); err == nil {
		t.Fatalf("expected the no-terminal confirmation guard to stop the uninstall, stdout:\\n%s", stdout.String())
	}

	out := stdout.String()
	if !strings.Contains(out, "could not be checked") {
		t.Fatalf("expected the summary to list agent hooks that could not be checked, got:\\n%s", out)
	}
	if !strings.Contains(out, agentName) {
		t.Errorf("summary must name the plugin %q whose state is unknown, got:\\n%s", agentName, out)
	}
}

