// probeScript returns a mock whose are-hooks-installed behaves as mode says:
// "installed", "absent", "crash", or "garbage".
func probeScript(mode string) string {
	base := mockInfoScript(validInfoJSON)
	var reply string
	switch mode {
	case "installed":
		reply = `echo '{"installed": true}'`
	case "absent":
		reply = `echo '{"installed": false}'`
	case "crash":
		reply = `echo 'plugin exploded' >&2; exit 3`
	case "garbage":
		reply = `echo 'not json at all'`
	}
	return strings.Replace(base,
		`  are-hooks-installed)
    echo '{"installed": true}'
    ;;`,
		"  are-hooks-installed)\n    "+reply+"\n    ;;", 1)
}

func TestProbeHooksInstalled(t *testing.T) {
	t.Parallel()

	tests := []struct {
		mode          string
		wantInstalled bool
		wantErr       bool
		// errContains pins that the plugin's own stderr survives into the error,
		// since that text is what the user is shown to act on.
		errContains string
	}{
		{mode: "installed", wantInstalled: true},
		{mode: "absent"},
		{mode: "crash", wantErr: true, errContains: "plugin exploded"},
		{mode: "garbage", wantErr: true, errContains: "invalid JSON"},
	}

	for _, tt := range tests {
		t.Run(tt.mode, func(t *testing.T) {
			t.Parallel()

			ea := newExternalAgent(t, testBinaryDir(t, probeScript(tt.mode)))

			installed, err := ea.probeHooksInstalled(context.Background())
			if tt.wantErr {
				if err == nil {
					t.Fatalf("probeHooksInstalled() error = nil, want an error for a plugin that cannot answer")
				}
				if tt.errContains != "" && !strings.Contains(err.Error(), tt.errContains) {
					t.Errorf("error = %q, want it to carry %q", err, tt.errContains)
				}
			} else if err != nil {
				t.Fatalf("probeHooksInstalled() error = %v", err)
			}
			if installed != tt.wantInstalled {
				t.Errorf("probeHooksInstalled() = %v, want %v", installed, tt.wantInstalled)
			}

			// AreHooksInstalled keeps swallowing the error: nine callers use it for
			// display, where a plugin that cannot answer has nothing to show.
			if got := ea.AreHooksInstalled(context.Background()); got != tt.wantInstalled {
				t.Errorf("AreHooksInstalled() = %v, want %v", got, tt.wantInstalled)
			}
		})
	}
}

